import 'dart:convert';
import 'package:flutter/widgets.dart';

/// Guess Number home screen image embedded directly in Dart.
/// No separate PNG asset or pubspec.yaml entry is required.
class GuessNumberHomeImage extends StatelessWidget {
  const GuessNumberHomeImage({super.key});

  static const String _imageBase64 = '';

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_imageBase64),
      fit: BoxFit.contain,
      width: double.infinity,
    );
  }
}
